    const renewed = (await ok(post(`/staff-contracts/${renewing.id}/renew`, { type: 'permanent', startsOn: isoDay(61) }, P), 201)).body as { id: string; status: string; startsOn: string };
    expect([renewed.status, renewed.startsOn]).toEqual(['upcoming', isoDay(61)]);
    const ended = await db().staffContract.findFirstOrThrow({ where: { schoolId, id: BigInt(renewing.id) } });
    expect([ended.endReason, ended.endedOn?.toISOString().slice(0, 10), ended.endedBy]).toEqual(['renewed', isoDay(60), P.userId]);
    expect(await db().staffContract.count({ where: { schoolId, staffId: SUB.staffId, endedAt: null } })).toBe(1);
