    expect([await warn(0), await warn(0), await warn(10), await warn(23), await warn(23), await warn(31)]).toEqual([1, 0, 0, 1, 0, 0]);
    expect((await db().staffContract.findFirstOrThrow({ where: { schoolId, id: BigInt(expiring.id) } })).endedAt).toBeNull();
    expect((await db().staff.findFirstOrThrow({ where: { schoolId, id: ET.staffId } })).status).toBe('active');

    // ===================================================================== punches and a dispute (R344-R347)
    const token = ((await ok(post('/school/device-token/rotate', {}, P), 200)).body as { token: string }).token;
