    expect((await post(`/staff-attendance-disputes/${dispute.id}/approve`, {}, CT)).status).toBe(403);
    expect((await ok(post(`/staff-attendance-disputes/${dispute.id}/approve`, { reason: 'Duty roster agrees' }, P), 200)).body).toMatchObject({ status: 'approved', markStatus: 'present' });
    expect((await db().staffAttendance.findFirstOrThrow({ where: { schoolId, id: BigInt(ctMark) } })).status).toBe('present');

    // ===================================================================== payroll
